//! Format-v1 compatibility (ADR 0033): journals written by every released version's own writer
//! (`tests/compat/fixtures/`, generated by `tests/compat/generate.sh`) are read, verified, recovered and continued by
//! the current code. Every test works on a fresh unpacked copy; the committed fixtures are only read.

#[path = "compat/sha256.rs"]
mod sha256;
#[path = "compat/support.rs"]
mod support;

use std::collections::BTreeSet;
use std::path::Path;
use std::time::Duration;

use tickertape::format::{self, Slot};
use tickertape::inspect::{self, SegmentEnd};
use tickertape::{
    CorruptReason, Error, NewRecord, OwnedRecord, Reader, ReaderConfig, RecoveryAction,
    RecoveryPolicy, Writer, WriterConfig,
};

use support::{Fixture, fixtures};

/// Released tags that must have fixtures. The release checklist adds each new release here together with its
/// fixtures (`docs/playbooks/release-checklist.md`).
const RELEASED_TAGS: &[&str] = &["v0.1.0", "v0.2.0", "v0.3.0", "v0.4.0"];
/// Platforms every released tag must have fixtures from.
const REQUIRED_PLATFORMS: &[&str] = &["linux-aarch64", "macos-aarch64"];

fn config() -> WriterConfig {
    WriterConfig::default().segment_size(65_536)
}

fn digest(records: &[OwnedRecord]) -> String {
    let mut h = sha256::Sha256::default();
    for r in records {
        sha256::add_record(
            &mut h,
            r.seq,
            r.schema_id,
            r.venue_ts_ns,
            r.local_ts_ns,
            &r.payload,
        );
    }
    h.hex()
}

fn collect(mut reader: Reader) -> Vec<OwnedRecord> {
    let mut out = Vec::new();
    while let Some(r) = reader.next_owned().expect("read") {
        out.push(r);
    }
    out
}

fn open(dir: &Path, durable_only: bool, mapped: bool) -> Reader {
    let config = ReaderConfig::default().durable_only(durable_only);
    if mapped {
        // SAFETY: only this test process touches the unpacked copy, and no writer is open while it reads.
        unsafe { Reader::open_mapped(dir, config) }.expect("open mapped reader")
    } else {
        Reader::open(dir, config).expect("open reader")
    }
}

fn check_stream(f: &Fixture, records: &[OwnedRecord], who: &str) {
    assert_eq!(
        records.len() as u64,
        f.u64("records"),
        "{}: {who} count",
        f.name
    );
    assert_eq!(
        records.first().map(|r| r.seq),
        Some(f.u64("first_seq")),
        "{}: {who}",
        f.name
    );
    assert_eq!(
        records.last().map(|r| r.seq),
        Some(f.u64("last_seq")),
        "{}: {who}",
        f.name
    );
    assert!(
        records.windows(2).all(|w| w[1].seq == w[0].seq + 1),
        "{}: {who} gap",
        f.name
    );
    assert_eq!(
        digest(records),
        f.str("stream_sha256"),
        "{}: {who} stream",
        f.name
    );
}

/// Every file's contents except `writer.lock` and `notify`, which a writer rewrites on open before recovery runs
/// and which hold no journal data (`docs/format.md` → Journal directory).
fn files_snapshot(dir: &Path) -> Vec<(String, Vec<u8>)> {
    let mut out = Vec::new();
    let mut stack = vec![dir.to_path_buf()];
    while let Some(d) = stack.pop() {
        for e in std::fs::read_dir(&d).unwrap() {
            let p = e.unwrap().path();
            if p.is_dir() {
                stack.push(p);
            } else {
                let name = p.strip_prefix(dir).unwrap().to_string_lossy().into_owned();
                if name != "writer.lock" && name != "notify" {
                    out.push((name, std::fs::read(&p).unwrap()));
                }
            }
        }
    }
    out.sort();
    out
}

#[test]
fn sha256_known_answers() {
    assert_eq!(
        sha256::hex(b""),
        "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
    );
    assert_eq!(
        sha256::hex(b"abc"),
        "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
    );
    assert_eq!(
        sha256::hex(b"abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq"),
        "248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1"
    );
    let mut h = sha256::Sha256::default();
    for _ in 0..1000 {
        h.update(&[b'a'; 1000]);
    }
    assert_eq!(
        h.hex(),
        "cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0"
    );
}

#[test]
fn pack_decoder_rejects_malformed_input() {
    let blob = std::fs::read(support::fixtures_dir().join(fixtures()[0].str("pack"))).unwrap();
    assert!(support::decode_pack(&blob).is_ok());
    assert!(support::decode_pack(&blob[..blob.len() - 1]).is_err());
    let mut extra = blob.clone();
    extra.push(0);
    assert!(support::decode_pack(&extra).is_err());
    let mut magic = blob;
    magic[0] ^= 1;
    assert!(support::decode_pack(&magic).is_err());
}

#[test]
fn every_release_has_fixtures() {
    let all = fixtures();
    let names: BTreeSet<&str> = all.iter().map(|f| f.name.as_str()).collect();
    for tag in RELEASED_TAGS {
        for platform in REQUIRED_PLATFORMS {
            for kind in ["clean", "torn"] {
                let name = format!("{tag}-{platform}-{kind}");
                assert!(names.contains(name.as_str()), "missing fixture {name}");
            }
        }
    }
    for f in &all {
        assert!(
            RELEASED_TAGS.contains(&f.str("tag")),
            "{}: tag not in RELEASED_TAGS",
            f.name
        );
        assert_eq!(f.str("library_version"), &f.str("tag")[1..], "{}", f.name);
        assert_eq!(f.str("commit").len(), 40, "{}", f.name);
        assert_eq!(
            f.name,
            format!(
                "{}-{}-{}-{}",
                f.str("tag"),
                f.str("os"),
                f.str("arch"),
                f.kind
            )
        );
        let files: Vec<&str> = f.json["files"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| x["name"].as_str().unwrap())
            .collect();
        // What each version leaves behind (CHANGELOG 0.3.0): `notify` since v0.3.0, and on macOS a prepared
        // `next-segment.tmp` when the writer was killed after preparing it.
        let v3 = f.str("tag") >= "v0.3.0";
        assert_eq!(files.contains(&"notify"), v3, "{}: notify", f.name);
        assert_eq!(
            files.contains(&"next-segment.tmp"),
            v3 && f.str("os") == "macos" && f.is_torn(),
            "{}: next-segment.tmp",
            f.name
        );
        assert!(files.contains(&"checkpoint") && files.contains(&"writer.lock"));
        assert!(
            f.json["segments"].as_array().unwrap().len() >= 4,
            "{}: rolls",
            f.name
        );
        assert!(f.checkpoint("next_seq") > f.u64("first_seq"));
        assert!(
            f.checkpoint("next_seq") < f.u64("next_seq"),
            "{}: uncovered tail",
            f.name
        );
    }
    // The whole set stays small (ADR 0033).
    let total: u64 = std::fs::read_dir(support::fixtures_dir())
        .unwrap()
        .map(|e| e.unwrap().metadata().unwrap().len())
        .sum();
    assert!(total < 1024 * 1024, "fixture set is {total} bytes");
}

#[test]
fn readers_return_the_manifest_stream() {
    for f in fixtures() {
        let (_tmp, dir) = f.unpack();
        for mapped in [false, true] {
            let who = if mapped { "mapped" } else { "safe" };
            check_stream(&f, &collect(open(&dir, false, mapped)), who);
            // Seeking lands on validated positions: the checkpoint boundary, the last record, and past the end.
            let mut r = open(&dir, false, mapped);
            r.seek(f.checkpoint("next_seq")).unwrap();
            assert_eq!(
                r.next_owned().unwrap().unwrap().seq,
                f.checkpoint("next_seq")
            );
            r.seek(f.u64("last_seq")).unwrap();
            assert_eq!(r.next_owned().unwrap().unwrap().seq, f.u64("last_seq"));
            assert!(
                r.try_next().unwrap().is_none(),
                "{}: {who} past the end",
                f.name
            );
            r.seek(f.u64("next_seq") + 5).unwrap();
            assert!(
                r.next_timeout(Some(Duration::from_millis(1)))
                    .unwrap()
                    .is_none()
            );
        }
    }
}

#[test]
fn durable_only_readers_stop_at_the_checkpoint() {
    for f in fixtures() {
        let (_tmp, dir) = f.unpack();
        let boundary = f.checkpoint("next_seq");
        for mapped in [false, true] {
            let mut reader = open(&dir, true, mapped);
            let mut records = Vec::new();
            while let Some(r) = reader.next_owned().unwrap() {
                records.push(r);
            }
            assert_eq!(records.len() as u64, f.u64("durable_records"), "{}", f.name);
            assert_eq!(records.last().unwrap().seq + 1, boundary, "{}", f.name);
            assert_eq!(
                digest(&records),
                f.str("durable_stream_sha256"),
                "{}",
                f.name
            );
            assert_eq!(reader.position(), boundary);
            assert!(
                reader
                    .next_timeout(Some(Duration::from_millis(20)))
                    .unwrap()
                    .is_none()
            );
        }
    }
}

#[test]
fn verify_and_inspect_report_the_manifest() {
    for f in fixtures() {
        let (_tmp, dir) = f.unpack();
        let report = inspect::verify(&dir).unwrap();
        assert!(
            report.problems.is_empty(),
            "{}: {:?}",
            f.name,
            report.problems
        );
        assert_eq!(report.records, f.u64("records"));
        assert_eq!(report.first_seq, Some(f.u64("first_seq")));
        assert_eq!(report.last_seq, Some(f.u64("last_seq")));
        let want = f.json["segments"].as_array().unwrap();
        assert_eq!(report.segments.len(), want.len(), "{}", f.name);
        for (got, want) in report.segments.iter().zip(want) {
            let info = got.info.as_ref().unwrap();
            assert_eq!(
                got.path.file_name().unwrap().to_str(),
                want["file"].as_str()
            );
            assert_eq!(info.base_seq, want["base_seq"].as_u64().unwrap());
            assert_eq!(info.segment_size, 65_536);
            assert_eq!(info.format_version, 1);
            assert_eq!(got.records, want["records"].as_u64().unwrap(), "{}", f.name);
            assert_eq!(got.end_seq, want["end_seq"].as_u64().unwrap());
            assert_eq!(got.used_bytes, want["used_bytes"].as_u64().unwrap());
            let end = match got.end {
                SegmentEnd::Sealed => "sealed",
                SegmentEnd::Open => "open",
                _ => "damaged",
            };
            assert_eq!(end, want["end"].as_str().unwrap(), "{}", f.name);
        }
        let checkpoint = inspect::read_checkpoint(&dir).unwrap().unwrap();
        assert_eq!(checkpoint.generation, f.checkpoint("generation"));
        assert_eq!(checkpoint.next_seq, f.checkpoint("next_seq"));
        assert_eq!(
            checkpoint.segment_base_seq,
            f.checkpoint("segment_base_seq")
        );
        assert_eq!(checkpoint.offset, f.checkpoint("offset"));
        assert_eq!(inspect::list_segments(&dir).unwrap().len(), want.len());
    }
}

/// Crash contract C1/C2 for a journal an old writer left behind: recovery keeps every committed record, zeroes only
/// the torn append's uncommitted bytes, quarantines nothing, and the current writer continues the sequence.
#[test]
fn current_writer_recovers_appends_and_checkpoints() {
    for f in fixtures() {
        let (_tmp, dir) = f.unpack();
        let had_spare = dir.join("next-segment.tmp").exists();
        let mut writer = Writer::open(&dir, config()).unwrap();
        let report = writer.recovery_report().clone();
        assert_eq!(report.next_seq, f.u64("next_seq"), "{}", f.name);
        assert!(report.had_checkpoint, "{}", f.name);
        assert_eq!(
            report.scanned_from_seq,
            f.checkpoint("next_seq"),
            "{}",
            f.name
        );
        let mut zeroed = 0;
        for action in &report.actions {
            match action {
                RecoveryAction::ZeroedUncommitted {
                    segment,
                    offset,
                    len,
                    ..
                } if f.is_torn() => {
                    let torn = &f.json["torn"];
                    assert_eq!(segment.file_name().unwrap().to_str(), torn["file"].as_str());
                    // The first non-zero byte at or after the torn append's commit word, through its last byte.
                    let (start, end) = (
                        torn["offset"].as_u64().unwrap(),
                        torn["uncommitted_end"].as_u64().unwrap(),
                    );
                    assert!((start..end).contains(offset), "{}: {action:?}", f.name);
                    assert!(offset + len >= end, "{}: {action:?}", f.name);
                    zeroed += 1;
                }
                RecoveryAction::RemovedTemp { file, .. } if had_spare => {
                    assert_eq!(file.file_name().unwrap(), "next-segment.tmp");
                }
                other => panic!("{}: unexpected recovery action {other:?}", f.name),
            }
        }
        assert_eq!(zeroed, u32::from(f.is_torn()), "{}", f.name);
        assert!(!dir.join("quarantine").exists(), "{}: quarantine", f.name);
        if f.is_torn() {
            let torn = &f.json["torn"];
            let image = std::fs::read(dir.join(torn["file"].as_str().unwrap())).unwrap();
            let offset = torn["offset"].as_u64().unwrap() as usize;
            assert!(
                image[offset..].iter().all(|&b| b == 0),
                "{}: torn bytes left",
                f.name
            );
        }

        // Continue the journal: small records, then large ones that roll twice, then a checkpoint.
        let start = writer.next_seq();
        let segments_before = inspect::list_segments(&dir).unwrap().len();
        let mut appended = Vec::new();
        for i in 0..40u64 {
            let len = if i % 13 == 12 {
                30_000
            } else {
                (i * 37 % 500) as usize
            };
            let payload: Vec<u8> = (0..len).map(|j| (i as usize * 7 + j) as u8).collect();
            let rec = NewRecord {
                schema_id: 9_000 + i as u32,
                venue_ts_ns: i,
                local_ts_ns: u64::MAX - i,
                payload: &payload,
            };
            let seq = writer.append(&rec).unwrap();
            assert_eq!(seq, start + i);
            appended.push(OwnedRecord {
                seq,
                schema_id: rec.schema_id,
                venue_ts_ns: rec.venue_ts_ns,
                local_ts_ns: rec.local_ts_ns,
                payload,
            });
        }
        writer.checkpoint().unwrap();
        drop(writer);
        assert!(inspect::list_segments(&dir).unwrap().len() >= segments_before + 2);

        let report = inspect::verify(&dir).unwrap();
        assert!(
            report.problems.is_empty(),
            "{}: {:?}",
            f.name,
            report.problems
        );
        assert_eq!(report.records, f.u64("records") + 40);
        for mapped in [false, true] {
            let all = collect(open(&dir, false, mapped));
            let (old, new) = all.split_at(f.u64("records") as usize);
            check_stream(&f, old, "reader after append");
            assert_eq!(new, appended.as_slice(), "{}", f.name);
            let durable = collect(open(&dir, true, mapped));
            assert_eq!(
                durable.len(),
                all.len(),
                "{}: checkpoint covers all",
                f.name
            );
        }
        let reopened = Writer::open(&dir, config()).unwrap();
        assert!(reopened.recovery_report().actions.is_empty(), "{}", f.name);
        assert_eq!(reopened.next_seq(), start + 40);
    }
}

/// Crash contract C8/C11 on an old journal: a corrupt record after the checkpoint is preserved in `quarantine/` and
/// cut off by replacing the segment (`Quarantine`), or refused without changing any byte (`Fail`).
#[test]
fn corrupt_tail_of_old_journal_is_quarantined_or_refused() {
    for f in fixtures().into_iter().filter(|f| !f.is_torn()) {
        // The last record of the newest segment: corrupt one payload byte.
        let newest = f.json["segments"]
            .as_array()
            .unwrap()
            .last()
            .unwrap()
            .clone();
        let name = newest["file"].as_str().unwrap();
        let base = newest["base_seq"].as_u64().unwrap();
        let last = f.u64("last_seq");
        let corrupt = |dir: &Path| -> (u64, Vec<u8>) {
            let path = dir.join(name);
            let mut image = std::fs::read(&path).unwrap();
            let (mut offset, mut seq) = (format::SEGMENT_HEADER_LEN as u64, base);
            loop {
                match format::read_slot(&image[..], offset, seq).unwrap() {
                    Slot::Record { next_offset, .. } if seq < last => {
                        offset = next_offset;
                        seq += 1;
                    }
                    Slot::Record { len, .. } => {
                        let at = (offset + u64::from(len) - 1) as usize;
                        image[at] ^= 0x40;
                        std::fs::write(&path, &image).unwrap();
                        return (offset, image[offset as usize..].to_vec());
                    }
                    other => panic!("{}: unexpected {other:?}", f.name),
                }
            }
        };

        let (_tmp, dir) = f.unpack();
        let (offset, tail) = corrupt(&dir);
        let before = files_snapshot(&dir);
        let refused = Writer::open(&dir, config().recovery(RecoveryPolicy::Fail));
        assert!(
            matches!(refused, Err(Error::Corrupt { offset: o, reason: CorruptReason::BadChecksum, .. }) if o == offset),
            "{}: {refused:?}",
            f.name
        );
        assert!(
            files_snapshot(&dir) == before,
            "{}: Fail changed a byte",
            f.name
        );

        let (_tmp, dir) = f.unpack();
        corrupt(&dir);
        let writer = Writer::open(&dir, config()).unwrap();
        assert_eq!(writer.next_seq(), last, "{}", f.name);
        let mut repaired = 0;
        for action in &writer.recovery_report().actions {
            if let RecoveryAction::RepairedTail {
                segment,
                offset: o,
                len,
                quarantine_file,
                reason,
                ..
            } = action
            {
                assert_eq!(segment.file_name().unwrap().to_str(), Some(name));
                assert_eq!(*o, offset);
                assert_eq!(*reason, CorruptReason::BadChecksum);
                // The removed range is [offset, segment end); the quarantine file keeps it through its last non-zero
                // byte (the rest is zeros).
                assert_eq!(offset + len, 65_536);
                let kept = std::fs::read(quarantine_file).unwrap();
                assert_eq!(kept, tail[..kept.len()], "{}: quarantined bytes", f.name);
                assert!(
                    tail[kept.len()..].iter().all(|&b| b == 0),
                    "{}: bytes lost",
                    f.name
                );
                assert!(!kept.is_empty());
                repaired += 1;
            } else {
                panic!("{}: unexpected recovery action {action:?}", f.name);
            }
        }
        assert_eq!(repaired, 1, "{}", f.name);
        drop(writer);
        let records = collect(open(&dir, false, false));
        assert_eq!(records.len() as u64, f.u64("records") - 1);
        assert!(inspect::verify(&dir).unwrap().problems.is_empty());
    }
}
